var a=`1429-breadfruit-with-coconut`;var r=`world-1429`;var n=`MH`;var i=`oceania`;var o=4;var u=54;var s={en:`Breadfruit with Coconut`,ua:`Хлібний плід із кокосом`};var m={en:`Marshall Islands-style breadfruit steamed until tender and served with warm coconut cream.`,ua:`Хлібний плід по-маршалльськи, приготовлений до м’якості та поданий з теплими кокосовими вершками.`};var d=[{en:`Peel and core a firm mature breadfruit. Cut flesh into even wedges.`,ua:`Очистіть стиглий, але щільний хлібний плід, видаліть серцевину й наріжте м’якоть однаковими часточками.`,t:[`peeling`],m:12,i:[[`breadfruit`,850,`g`]]},{en:`Arrange breadfruit in a steamer and cook over boiling water 25–35 minutes until tender all the way through.`,ua:`Викладіть хлібний плід у пароварку та готуйте над киплячою водою 25–35 хвилин до повної м’якості.`,t:[`steaming`],m:35,i:[[`water`,1e3,`ml`]]},{en:`Warm coconut cream with a pinch of salt for 4–5 minutes without a hard boil.`,ua:`Підігрійте кокосові вершки з дрібкою солі 4–5 хвилин, не доводячи до сильного кипіння.`,t:[`gentle-simmering`],m:5,i:[[`coconut-cream`,300,`ml`],[`sea-salt`,3,`g`]]},{en:`Spoon coconut cream over warm breadfruit wedges and serve.`,ua:`Полийте теплі часточки хлібного плоду кокосовими вершками й подавайте.`,t:[`garnishing`],m:2,i:[]}];var l={slug:a,id:r,country:`MH`,region:i,servings:4,minutes:54,title:s,text:m,steps:d};export{n as country,l as default,r as id,u as minutes,i as region,o as servings,a as slug,d as steps,m as text,s as title};